import React from 'react';

export default function AirlineEventList({ initialEvents, airlineId }: { initialEvents: any[]; airlineId: string }) {
  return (
    <div className="space-y-4">
      {initialEvents.map((event) => (
        <div key={event.id} className="card">
          <h2 className="text-lg font-bold">{event.title}</h2>
          <p className="text-sm text-gray-600">{event.description}</p>
          <p className="text-sm text-gray-500">
            {event.startDate ? `Start: ${new Date(event.startDate).toLocaleDateString()}` : 'No Start Date'}
          </p>
          <p className="text-sm text-gray-500">
            {event.endDate ? `End: ${new Date(event.endDate).toLocaleDateString()}` : 'No End Date'}
          </p>
        </div>
      ))}
    </div>
  );
}